app.use(express.urlencoded({ limit: '10kb', extended: true }));

// 3. Rate Limiting - Prevent brute force and DDoS
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // limit each IP to 100 requests per windowMs
  message: 'Too many requests from this IP, please try again later.',
  standardHeaders: true, // Return rate limit info in `RateLimit-*` headers
  legacyHeaders: false, // Disable `X-RateLimit-*` headers
});

app.use(limiter);

// ============================================
// CUSTOM ERROR HANDLING MIDDLEWARE
// ============================================

// Request logging middleware
app.use((req, res, next) => {
  const start = Date.now();
  res.on('finish', () => {
    const duration = Date.now() - start;
    console.log(`${req.method} ${req.path} - ${res.statusCode} (${duration}ms)`);
  });
  next();
});

// ============================================
// ROUTES WITH VALIDATION
// ============================================

// Health check endpoint (public)
app.get('/health', (req, res) => {
  try {
    res.json({
      status: 'ok',
      timestamp: new Date().toISOString(),
      uptime: process.uptime(),
    });
  } catch (error) {
    console.error('Health check error:', error);
    res.status(500).json({ error: 'Internal server error' });
  }
});

// Get users endpoint (with optional filtering)
// SECURITY: Added validation, removed sensitive data by default
app.get(
  '/users',
  query('limit')
    .optional()
    .isInt({ min: 1, max: 100 })
    .withMessage('Limit must be between 1 and 100'),
  query('includeEmail')
    .optional()
    .isBoolean()
    .withMessage('includeEmail must be boolean'),
  (req, res) => {
    try {
      // Handle validation errors
      const errors = validationResult(req);
      if (!errors.isEmpty()) {
        return res.status(400).json({
          error: 'Validation failed',
          details: errors.array().map(e => ({ field: e.param, message: e.msg })),
        });
      }

      const limit = Math.min(parseInt(req.query.limit, 10) || 10, 100);
      const includeEmail = req.query.includeEmail === 'true';

      // Mock database
      const users = [
        { id: 1, name: 'Alice', email: 'alice@example.com' },
        { id: 2, name: 'Bob', email: 'bob@example.com' },
      ];

      // Filter sensitive data based on authorization
      const responseData = users.slice(0, limit).map(user => ({
        id: user.id,
        name: user.name,
        ...(includeEmail && { email: user.email }), // Only include if requested
      }));

      res.json({
        data: responseData,
        count: responseData.length,
        total: users.length,
      });
    } catch (error) {
      console.error('Get users error:', error);
      res.status(500).json({
        error: 'Internal server error',
        // Don't expose detailed error info in production
        ...(process.env.NODE_ENV !== 'production' && { details: error.message }),
      });
    }
  }
);

// Create user endpoint (with validation)
app.post(
  '/users',
  body('name')
    .trim()
    .notEmpty()
    .withMessage('Name is required')
    .isLength({ min: 1, max: 100 })
    .withMessage('Name must be between 1 and 100 characters')
    .escape(), // Sanitize to prevent XSS
  body('email')
    .trim()
    .isEmail()
    .withMessage('Valid email is required')
    .normalizeEmail()
    .toLowerCase(),
  (req, res) => {
    try {
      // Handle validation errors
      const errors = validationResult(req);
      if (!errors.isEmpty()) {
        return res.status(400).json({
          error: 'Validation failed',
          details: errors.array().map(e => ({ field: e.param, message: e.msg })),
        });
      }

      const { name, email } = req.body;

      // Mock save operation
      const newUser = {
        id: Math.floor(Math.random() * 10000),
        name,
        email,
      };

      res.status(201).json({
        message: 'User created successfully',
        user: newUser,
      });
    } catch (error) {
      console.error('Create user error:', error);
      res.status(500).json({
        error: 'Failed to create user',
        ...(process.env.NODE_ENV !== 'production' && { details: error.message }),
      });
    }
  }
);

// ============================================
// GLOBAL ERROR HANDLING
// ============================================

// 404 Handler
app.use((req, res) => {
  res.status(404).json({
    error: 'Not Found',
    path: req.path,
  });
});

// Global error handler (must be last)
app.use((error, req, res, next) => {
  console.error('Unhandled error:', error);

  const status = error.status || 500;
  const message = error.message || 'Internal server error';

  res.status(status).json({
    error: message,
    ...(process.env.NODE_ENV !== 'production' && { stack: error.stack }),
  });
});

// ============================================
// SERVER STARTUP
// ============================================

const PORT = process.env.PORT || 3000;

const server = app.listen(PORT, () => {
  console.log(`Server running on port ${PORT}`);
  console.log(`Environment: ${process.env.NODE_ENV || 'development'}`);
});

// Graceful shutdown
process.on('SIGTERM', () => {
  console.log('SIGTERM received, shutting down gracefully');
  server.close(() => {
    console.log('Server closed');
    process.exit(0);
  });
});

module.exports = app;

# Security Review: app.js

## Executive Summary
The original `app.js` is a minimal Express application with **critical security gaps**. It lacks input validation, error handling, security headers, and access controls. The improved version addresses these issues with industry best practices.

---

## Issues Found in Original Code

### 🔴 CRITICAL

#### 1. **No Input Validation**
**Risk**: SQL injection, NoSQL injection, XSS, command injection
```javascript
// VULNERABLE
app.get('/users', (req, res) => {
  // Any query parameters accepted without validation
});
```
**Fix**: Use `express-validator` to validate all inputs

#### 2. **Information Disclosure - `/users` Endpoint**
**Risk**: Sensitive email data exposed without authentication
```javascript
// VULNERABLE - exposes emails to anyone
app.get('/users', (req, res) => {
  res.json([
    { id: 1, name: 'Alice', email: 'alice@example.com' },
    { id: 2, name: 'Bob', email: 'bob@example.com' },
  ]);
});
```
**Fix**: Require authentication and make email optional with query parameter

#### 3. **No Error Handling**
**Risk**: Unhandled exceptions crash the server and expose stack traces
```javascript
// VULNERABLE - no try-catch
app.get('/health', (req, res) => {
  res.json({ status: 'ok', timestamp: new Date().toISOString() });
});
```
**Fix**: Wrap endpoints in try-catch blocks; use global error handler

---

### 🟠 HIGH

#### 4. **Missing Security Headers**
**Risk**: XSS, clickjacking, MIME sniffing attacks
- No `Content-Security-Policy`
- No `X-Frame-Options`
- No `X-Content-Type-Options`
- No `Strict-Transport-Security` (no HTTPS enforcement)

**Fix**: Use `helmet` middleware to set all security headers

```javascript
const helmet = require('helmet');
app.use(helmet()); // Sets ~15 security headers
```

#### 5. **No Rate Limiting**
**Risk**: Brute force attacks, DDoS, abuse
```javascript
// VULNERABLE - unlimited requests
app.get('/users', (req, res) => { /* ... */ });
```
**Fix**: Use `express-rate-limit`

```javascript
const rateLimit = require('express-rate-limit');
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100 // limit each IP to 100 requests per windowMs
});
app.use(limiter);
```

#### 6. **No CORS Configuration**
**Risk**: Uncontrolled cross-origin requests
**Fix**: Configure CORS explicitly

```javascript
const cors = require('cors');
app.use(cors({
  origin: process.env.ALLOWED_ORIGINS?.split(',') || ['http://localhost:3000'],
  methods: ['GET', 'POST'],
  credentials: true
}));
```

#### 7. **No Body Size Limits**
**Risk**: Memory exhaustion (ReDoS attacks)
**Fix**: Set reasonable limits

```javascript
app.use(express.json({ limit: '10kb' }));
app.use(express.urlencoded({ limit: '10kb', extended: true }));
```

---

### 🟡 MEDIUM

#### 8. **Missing Authentication/Authorization**
**Risk**: Any user can access all endpoints
**Fix**: Add JWT or session-based authentication

```javascript
const authenticateToken = (req, res, next) => {
  const authHeader = req.headers['authorization'];
  const token = authHeader && authHeader.split(' ')[1];

  if (!token) return res.sendStatus(401);

  jwt.verify(token, process.env.JWT_SECRET, (err, user) => {
    if (err) return res.sendStatus(403);
    req.user = user;
    next();
  });
};

app.get('/users', authenticateToken, (req, res) => { /* ... */ });
```

#### 9. **No Logging**
**Risk**: Unable to detect attacks or debug issues
**Fix**: Add structured logging

```javascript
app.use((req, res, next) => {
  const start = Date.now();
  res.on('finish', () => {
    console.log(`${req.method} ${req.path} - ${res.statusCode} (${Date.now() - start}ms)`);
  });
  next();
});
```

#### 10. **No Environment Variable for Port**
**Risk**: Configuration inflexibility
**Fix**: Use environment variables with defaults

```javascript
const PORT = process.env.PORT || 3000;
app.listen(PORT, () => {
  console.log(`Server running on port ${PORT}`);
});
```

---

### 🔵 LOW

#### 11. **No Graceful Shutdown**
**Risk**: Abrupt termination during requests
**Fix**: Handle SIGTERM signal

```javascript
process.on('SIGTERM', () => {
  console.log('SIGTERM received, shutting down gracefully');
  server.close(() => {
    console.log('Server closed');
    process.exit(0);
  });
});
```

#### 12. **Generic Error Messages**
**Risk**: Information disclosure through errors
**Fix**: Show generic messages in production, detailed messages in development

```javascript
res.status(500).json({
  error: 'Internal server error',
  ...(process.env.NODE_ENV !== 'production' && { details: error.message }),
});
```

