    expect(res.body.timestamp).toBeDefined();
  });
});

describe('GET /users', () => {
  it('should return users list', async () => {
    const res = await request(app)
      .get('/users')
      .expect(200);

    expect(Array.isArray(res.body.data)).toBe(true);
    expect(res.body.data[0]).toHaveProperty('id');
    expect(res.body.data[0]).toHaveProperty('name');
    expect(res.body.data[0]).not.toHaveProperty('email');
  });

  it('should include email when requested', async () => {
    const res = await request(app)
      .get('/users?includeEmail=true')
      .expect(200);

    expect(res.body.data[0]).toHaveProperty('email');
  });

  it('should validate limit parameter', async () => {
    const res = await request(app)
      .get('/users?limit=invalid')
      .expect(400);

    expect(res.body.error).toBe('Validation failed');
  });

  it('should enforce max limit of 100', async () => {
    const res = await request(app)
      .get('/users?limit=1000')
      .expect(200);

    expect(res.body.count).toBeLessThanOrEqual(100);
  });
});

describe('POST /users', () => {
  it('should create a user with valid data', async () => {
    const res = await request(app)
      .post('/users')
      .send({ name: 'John', email: 'john@example.com' })
      .expect(201);

    expect(res.body.user).toHaveProperty('id');
    expect(res.body.user.name).toBe('John');
  });

  it('should reject invalid email', async () => {
    const res = await request(app)
      .post('/users')
      .send({ name: 'John', email: 'invalid' })
      .expect(400);

    expect(res.body.error).toBe('Validation failed');
  });

  it('should reject missing name', async () => {
    const res = await request(app)
      .post('/users')
      .send({ email: 'john@example.com' })
      .expect(400);

    expect(res.body.error).toBe('Validation failed');
  });
});

describe('Rate Limiting', () => {
  it('should rate limit excessive requests', async () => {
    const requests = [];
    for (let i = 0; i < 110; i++) {
      requests.push(request(app).get('/health'));
    }

    const responses = await Promise.all(requests);
    const rateLimited = responses.filter(r => r.status === 429);

    expect(rateLimited.length).toBeGreaterThan(0);
  });
});

describe('Error Handling', () => {
  it('should return 404 for unknown routes', async () => {
    const res = await request(app)
      .get('/unknown')
      .expect(404);

    expect(res.body.error).toBe('Not Found');
  });
});
