input.script:
export const meta = {
  name: 'app-js-security-review',
  description: 'Security review of app.js for error handling, input validation, and best practices',
  phases: [
    { title: 'Find Candidates', detail: 'Multiple angles: security, error handling, validation, best practices' },
    { title: 'Verify Findings', detail: 'Validate each candidate finding' }
  ]
}

const DIFF = `
const express = require('express');
const app = express();

app.get('/health', (req, res) => {
  res.json({ status: 'ok', timestamp: new Date().toISOString() });
});

app.get('/users', (req, res) => {
  res.json([
    { id: 1, name: 'Alice', email: 'alice@example.com' },
    { id: 2, name: 'Bob', email: 'bob@example.com' },
  ]);
});

app.listen(3000, () => {
  console.log('Server running on port 3000');
});

module.exports = app;
`;

phase('Find Candidates')

// Angle 1: Security vulnerabilities
const securityIssues = await agent(
  `Analyze this Express.js code for security vulnerabilities. Look for:
  - Missing CORS/security headers
  - No authentication/authorization
  - Exposed sensitive data
  - Missing input validation/sanitization
  - No rate limiting/DoS protection
  - Unhandled errors that could leak info

  Code:
  ${DIFF}`,
  {
    label: 'security-vulnerabilities',
    phase: 'Find Candidates',
    schema: {
      type: 'object',
      properties: {
        issues: {
          type: 'array',
          items: {
            type: 'object',
            properties: {
              summary: { type: 'string' },
              line: { type: 'number' },
              severity: { type: 'string', enum: ['high', 'medium', 'low'] },
              description: { type: 'string' }
            }
          }
        }
      }
    }
  }
)

// Angle 2: Error handling gaps
const errorHandling = await agent(
  `Review this Express.js app for error handling issues:
  - Missing try-catch blocks
  - Unhandled promise rejections
  - No global error middleware
  - Missing status codes for edge cases
  - Console.log instead of proper logging

  Code:
  ${DIFF}`,
  {
    label: 'error-handling',
    phase: 'Find Candidates',
    schema: {
      type: 'object',
      properties: {
        issues: {
          type: 'array',
          items: {
            type: 'object',
            properties: {
              summary: { type: 'string' },
              line: { type: 'number' },
              impact: { type: 'string' }
            }
          }
        }
      }
    }
  }
)

// Angle 3: Input validation
const inputValidation = await agent(
  `Analyze this Express.js code for input validation gaps:
  - Query parameter validation
  - Path parameter validation
  - Request body validation (if applicable)
  - Missing sanitization
  - Type checking

  Code:
  ${DIFF}`,
  {
    label: 'input-validation',
    phase: 'Find Candidates',
    schema: {
      type: 'object',
      properties: {
        issues: {
          type: 'array',
          items: {
            type: 'object',
            properties: {
              summary: { type: 'string' },
              line: { type: 'number' },
              exploitScenario: { type: 'string' }
            }
          }
        }
      }
    }
  }
)

// Angle 4: Best practices
const bestPractices = await agent(
  `Review this Express.js app for best practice violations:
  - Hardcoded configuration (port, credentials)
  - Missing middleware
  - No logging
  - No monitoring/health checks
  - Module organization
  - Environment-specific setup

  Code:
  ${DIFF}`,
  {
    label: 'best-practices',
    phase: 'Find Candidates',
    schema: {
      type: 'object',
      properties: {
        issues: {
          type: 'array',
          items: {
            type: 'object',
            properties: {
              summary: { type: 'string' },
              line: { type: 'number' },
              recommendation: { type: 'string' }
            }
          }
        }
      }
    }
  }
)

// Collect all candidates
const allCandidates = [
  ...(securityIssues.issues || []).map(i => ({...i, category: 'security'})),
  ...(errorHandling.issues || []).map(i => ({...i, category: 'error-handling'})),
  ...(inputValidation.issues || []).map(i => ({...i, category: 'input-validation'})),
  ...(bestPractices.issues || []).map(i => ({...i, category: 'best-practices'}))
]

log(`Found ${allCandidates.length} candidate issues across 4 angles`)

phase('Verify Findings')

// Verify each unique candidate
const verified = await parallel(
  allCandidates.slice(0, 15).map(candidate => () =>
    agent(
      `Verify this code issue is real. Given the Express.js code:

${DIFF}

Evaluate this candidate finding:
- Category: ${candidate.category}
- Summary: ${candidate.summary}
- Line: ${candidate.line}
- Description/Impact: ${candidate.description || candidate.impact || candidate.exploitScenario || candidate.recommendation}

Is this a REAL issue that needs fixing? Return exactly: CONFIRMED if real and actionable, PLAUSIBLE if likely true, or REFUTED if false/not applicable.`,
      {
        label: `verify:${candidate.category}:${candidate.line}`,
        phase: 'Verify Findings'
      }
    )
    .then(result => ({
      ...candidate,
      verdict: result.includes('CONFIRMED') ? 'CONFIRMED' : 
               result.includes('PLAUSIBLE') ? 'PLAUSIBLE' : 'REFUTED'
    }))
  )
)

const confirmed = verified.filter(v => v.verdict === 'CONFIRMED' || v.verdict === 'PLAUSIBLE')

log(`Verified: ${confirmed.length} issues confirmed/plausible`)

return {
  totalCandidates: allCandidates.length,
  verified: confirmed.map(c => ({
    category: c.category,
    summary: c.summary,
    line: c.line,
    verdict: c.verdict
  }))
}

