// Secure Express application with error handling and validation
const express = require('express');
const helmet = require('helmet');
const rateLimit = require('express-rate-limit');
const validator = require('validator');
const app = express();

// ==================== SECURITY MIDDLEWARE ====================

// Set security HTTP headers
app.use(helmet());

// Rate limiting - prevent brute force and DoS attacks
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // limit each IP to 100 requests per windowMs
  message: 'Too many requests from this IP, please try again later.',
  standardHeaders: true, // Return rate limit info in the `RateLimit-*` headers
  legacyHeaders: false, // Disable the `X-RateLimit-*` headers
});

app.use(limiter);

// Body parser middleware with size limits
app.use(express.json({ limit: '10kb' })); // Prevent large payload attacks
app.use(express.urlencoded({ limit: '10kb', extended: true }));

// ==================== LOGGING MIDDLEWARE ====================

// Simple request logger (replace with Morgan or Bunyan in production)
app.use((req, res, next) => {
  const start = Date.now();
  res.on('finish', () => {
    const duration = Date.now() - start;
    console.log(`[${new Date().toISOString()}] ${req.method} ${req.path} - ${res.statusCode} (${duration}ms)`);
  });
  next();
});

// ==================== ROUTES ====================

// Health check endpoint
app.get('/health', (req, res) => {
  try {
    res.json({
      status: 'ok',
      timestamp: new Date().toISOString(),
      uptime: process.uptime()
    });
  } catch (error) {
    console.error('Health check error:', error);
    res.status(500).json({ status: 'error', message: 'Internal server error' });
  }
});

// Get users endpoint with validation
app.get('/users', (req, res) => {
  try {
    // Validate query parameters if present
    const { limit, skip } = req.query;

    // Input validation with sanitization
    let parsedLimit = 10; // Default limit
    let parsedSkip = 0;   // Default skip

    if (limit !== undefined) {
      // Validate that limit is a positive integer
      if (!validator.isInt(limit, { min: 1, max: 100 })) {
        return res.status(400).json({
          error: 'Invalid limit parameter. Must be an integer between 1 and 100.'
        });
      }
      parsedLimit = parseInt(limit, 10);
    }

    if (skip !== undefined) {
      // Validate that skip is a non-negative integer
      if (!validator.isInt(skip, { min: 0 })) {
        return res.status(400).json({
          error: 'Invalid skip parameter. Must be a non-negative integer.'
        });
      }
      parsedSkip = parseInt(skip, 10);
    }

    // Mock user data (in production, fetch from database)
    const allUsers = [
      { id: 1, name: 'Alice', email: 'alice@example.com' },
      { id: 2, name: 'Bob', email: 'bob@example.com' },
    ];

    // Apply pagination with validated parameters
    const users = allUsers.slice(parsedSkip, parsedSkip + parsedLimit);

    res.json({
      data: users,
      pagination: {
        limit: parsedLimit,
        skip: parsedSkip,
        total: allUsers.length
      }
    });
  } catch (error) {
    console.error('Get users error:', error);
    res.status(500).json({ error: 'Internal server error' });
  }
});

// ==================== ERROR HANDLING ====================

// 404 Not Found handler
app.use((req, res) => {
  res.status(404).json({ error: 'Not Found' });
});

// Global error handler (must be last)
app.use((err, req, res, next) => {
  console.error('Unhandled error:', {
    message: err.message,
    stack: err.stack,
    path: req.path,
    method: req.method,
  });

  // Don't expose internal error details to client
  res.status(err.status || 500).json({
    error: err.status === 404 ? 'Not Found' : 'Internal Server Error',
    // Only include error details in development
    ...(process.env.NODE_ENV === 'development' && { details: err.message }),
  });
});

// ==================== SERVER SETUP ====================

const PORT = process.env.PORT || 3000;
const NODE_ENV = process.env.NODE_ENV || 'development';

const server = app.listen(PORT, () => {
  console.log(`[${NODE_ENV}] Server running on port ${PORT}`);
});

// Handle unhandled promise rejections
process.on('unhandledRejection', (reason, promise) => {
  console.error('Unhandled Rejection at:', promise, 'reason:', reason);
  // In production, you should implement proper error tracking (e.g., Sentry)
});

// Handle uncaught exceptions
process.on('uncaughtException', (error) => {
  console.error('Uncaught Exception:', error);
  // Gracefully shutdown in production
  process.exit(1);
});

// Graceful shutdown
process.on('SIGTERM', () => {
  console.log('SIGTERM received, shutting down gracefully...');
  server.close(() => {
    console.log('Server closed');
    process.exit(0);
  });
});

module.exports = app;

