const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // Limit each IP to 100 requests per windowMs
  message: 'Too many requests from this IP',
  standardHeaders: true, // Return rate limit info in `RateLimit-*` headers
  legacyHeaders: false, // Disable `X-RateLimit-*` headers
});

app.use(limiter);

// CORS configuration
app.use((req, res, next) => {
  res.header('Access-Control-Allow-Origin', process.env.ALLOWED_ORIGINS || 'http://localhost:3000');
  res.header('Access-Control-Allow-Methods', 'GET, POST, OPTIONS');
  res.header('Access-Control-Allow-Headers', 'Content-Type, Authorization');
  next();
});

// ============ MIDDLEWARE FOR VALIDATION ============

// Validate JSON content-type
const validateContentType = (req, res, next) => {
  if (req.method === 'POST' && !req.is('json')) {
    return res.status(400).json({ error: 'Content-Type must be application/json' });
  }
  next();
};

app.use(validateContentType);

// ============ ROUTES ============

// Health check endpoint (public)
app.get('/health', (req, res) => {
  try {
    res.json({
      status: 'ok',
      timestamp: new Date().toISOString(),
      uptime: process.uptime()
    });
  } catch (error) {
    res.status(500).json({ error: 'Health check failed' });
  }
});

// Protected users endpoint with authentication
app.get('/users', authenticateToken, (req, res) => {
  try {
    // Validate query parameters
    const limit = validateLimit(req.query.limit);
    const offset = validateOffset(req.query.offset);

    const allUsers = [
      { id: 1, name: 'Alice', email: 'alice@example.com' },
      { id: 2, name: 'Bob', email: 'bob@example.com' },
    ];

    const users = allUsers.slice(offset, offset + limit);

    res.json({
      data: users,
      total: allUsers.length,
      limit,
      offset
    });
  } catch (error) {
    handleError(res, error, 'Failed to fetch users');
  }
});

// ============ HELPER FUNCTIONS ============

// Authentication middleware
function authenticateToken(req, res, next) {
  const authHeader = req.headers['authorization'];
  const token = authHeader && authHeader.split(' ')[1];

  if (!token) {
    return res.status(401).json({ error: 'Access token required' });
  }

  // Validate token format and content
  if (!/^[a-zA-Z0-9\-_.]+$/.test(token)) {
    return res.status(401).json({ error: 'Invalid token format' });
  }

  // TODO: Implement proper JWT validation with RS256
  // For now, basic token validation
  if (token !== process.env.AUTH_TOKEN) {
    return res.status(403).json({ error: 'Invalid token' });
  }

  next();
}

// Validate limit parameter
function validateLimit(limit) {
  const parsed = parseInt(limit, 10);
  if (isNaN(parsed) || parsed < 1) return 10;
  if (parsed > 100) return 100; // Max limit
  return parsed;
}

// Validate offset parameter
function validateOffset(offset) {
  const parsed = parseInt(offset, 10);
  if (isNaN(parsed) || parsed < 0) return 0;
  return parsed;
}

// Centralized error handler
function handleError(res, error, message) {
  console.error(`[ERROR] ${message}:`, error);

  if (error instanceof ValidationError) {
    return res.status(400).json({ error: message, details: error.message });
  }

  // Don't expose internal error details to clients
  res.status(500).json({ error: message || 'Internal server error' });
}

// Custom validation error class
class ValidationError extends Error {
  constructor(message) {
    super(message);
    this.name = 'ValidationError';
  }
}

// ============ 404 & ERROR HANDLERS ============

// 404 handler
app.use((req, res) => {
  res.status(404).json({ error: 'Not found' });
});

// Global error handler
app.use((err, req, res, next) => {
  console.error('[UNCAUGHT ERROR]:', err);
  res.status(err.status || 500).json({
    error: 'Internal server error',
    message: process.env.NODE_ENV === 'development' ? err.message : undefined
  });
});

// ============ SERVER STARTUP ============

const PORT = process.env.PORT || 3000;

const server = app.listen(PORT, () => {
  console.log(`Server running on port ${PORT}`);
  console.log(`Environment: ${process.env.NODE_ENV || 'development'}`);
});

// Graceful shutdown
process.on('SIGTERM', () => {
  console.log('SIGTERM received, shutting down gracefully');
  server.close(() => {
    console.log('Server closed');
    process.exit(0);
  });
});

module.exports = app;

