    ...(isDevelopment && { stack: err.stack }),
  });
};

// === ROUTES ===

// Health check endpoint
app.get('/health', (req, res) => {
  try {
    res.json({
      status: 'ok',
      timestamp: new Date().toISOString(),
      uptime: process.uptime(),
    });
  } catch (error) {
    res.status(500).json({ status: 'error', message: 'Health check failed' });
  }
});

// Get all users with pagination validation
app.get('/users', (req, res, next) => {
  try {
    // Validate query parameters
    const page = req.query.page ? parseInt(req.query.page, 10) : 1;
    const limit = req.query.limit ? parseInt(req.query.limit, 10) : 10;

    // Validate pagination
    if (isNaN(page) || page < 1) {
      return res.status(400).json({ status: 'error', message: 'Invalid page number' });
    }
    if (isNaN(limit) || limit < 1 || limit > 100) {
      return res.status(400).json({ status: 'error', message: 'Limit must be between 1 and 100' });
    }

    // Mock data
    const users = [
      { id: 1, name: 'Alice', email: 'alice@example.com' },
      { id: 2, name: 'Bob', email: 'bob@example.com' },
    ];

    res.json({
      status: 'success',
      data: users,
      pagination: { page, limit, total: users.length },
    });
  } catch (error) {
    next(error);
  }
});

// Get specific user with validation
app.get('/users/:id', (req, res, next) => {
  try {
    const { valid, error, id } = validateUserId(req.params.id);

    if (!valid) {
      return res.status(400).json({ status: 'error', message: error });
    }

    // Mock data
    const users = [
      { id: 1, name: 'Alice', email: 'alice@example.com' },
      { id: 2, name: 'Bob', email: 'bob@example.com' },
    ];

    const user = users.find(u => u.id === id);

    if (!user) {
      return res.status(404).json({ status: 'error', message: 'User not found' });
    }

    res.json({ status: 'success', data: user });
  } catch (error) {
    next(error);
  }
});

// 404 handler
app.use((req, res) => {
  res.status(404).json({ status: 'error', message: 'Route not found' });
});

// Error handling middleware (must be last)
app.use(globalErrorHandler);

// === SERVER STARTUP ===
const server = app.listen(PORT, () => {
  console.log(`[${NODE_ENV.toUpperCase()}] Server running on port ${PORT}`);
});

// Graceful shutdown
process.on('SIGTERM', () => {
  console.log('SIGTERM received, shutting down gracefully...');
  server.close(() => {
    console.log('Server closed');
    process.exit(0);
  });
});

// Unhandled rejection handler
process.on('unhandledRejection', (reason, promise) => {
  console.error('Unhandled Rejection at:', promise, 'reason:', reason);
  process.exit(1);
});

module.exports = app;
