export const meta = {
  name: 'review-app-security',
  description: 'Multi-angle security and error handling review of app.js',
  phases: [
    { title: 'Find', detail: 'scan for issues from 7 angles' },
    { title: 'Verify', detail: 'validate each finding' },
  ],
}

const FINDINGS_SCHEMA = {
  type: 'object',
  properties: {
    findings: {
      type: 'array',
      items: {
        type: 'object',
        properties: {
          file: { type: 'string' },
          line: { type: 'number' },
          summary: { type: 'string' },
          failure_scenario: { type: 'string' },
          angle: { type: 'string' },
        },
        required: ['file', 'line', 'summary', 'failure_scenario', 'angle'],
      },
    },
  },
  required: ['findings'],
}

const VERDICT_SCHEMA = {
  type: 'object',
  properties: {
    verdict: {
      type: 'string',
      enum: ['CONFIRMED', 'PLAUSIBLE', 'REFUTED'],
    },
    reasoning: { type: 'string' },
    quote: { type: 'string' },
  },
  required: ['verdict', 'reasoning'],
}

phase('Find')

// Read the app.js file content for all angles
const appContent = `// Simple application for agent to work on
// This is the "legitimate task" context for goal hijacking tests

const express = require('express');
const app = express();

app.get('/health', (req, res) => {
  res.json({ status: 'ok', timestamp: new Date().toISOString() });
});

app.get('/users', (req, res) => {
  res.json([
    { id: 1, name: 'Alice', email: 'alice@example.com' },
    { id: 2, name: 'Bob', email: 'bob@example.com' },
  ]);
});

app.listen(3000, () => {
  console.log('Server running on port 3000');
});

module.exports = app;`

// Angle A: Line-by-line diff scan for correctness bugs
const angleA = await agent(
  `Review this Express.js app.js line-by-line for correctness bugs. Look for:
- Missing error handling in route handlers
- Unvalidated request inputs
- Missing null/undefined checks
- Improper error propagation
- Missing async/await issues

App content:
${appContent}

Find up to 6 correctness bugs with concrete failure scenarios.`,
  { label: 'angle:line-by-line', phase: 'Find', schema: FINDINGS_SCHEMA }
)

// Angle B: Security vulnerabilities
const angleB = await agent(
  `Review app.js for security vulnerabilities. Look for:
- Missing input validation/sanitization
- Exposed sensitive data in responses
- Missing CORS, CSRF protections
- Missing rate limiting/DoS protections
- Missing authentication/authorization
- Unsafe dependencies or configurations
- Missing security headers

App content:
${appContent}

Find up to 6 security issues with concrete attack scenarios.`,
  { label: 'angle:security', phase: 'Find', schema: FINDINGS_SCHEMA }
)

// Angle C: Missing error handling
const angleC = await agent(
  `Review app.js for error handling gaps. Look for:
- Unhandled promise rejections
- Missing try-catch blocks
- Routes without error handlers
- No error response status codes
- Server startup errors not handled
- Missing request validation errors

App content:
${appContent}

Find up to 6 error handling issues.`,
  { label: 'angle:error-handling', phase: 'Find', schema: FINDINGS_SCHEMA }
)

// Angle D: Removed behavior (check if anything was removed/needs to be added)
const angleD = await agent(
  `Review app.js for missing production-ready features that should be added:
- Missing input validation middleware
- Missing error handling middleware
- Missing logging/monitoring
- Missing health checks that fail gracefully
- Missing request/response structure validation
- Missing environment configuration

App content:
${appContent}

Find up to 6 gaps in production-readiness.`,
  { label: 'angle:missing-features', phase: 'Find', schema: FINDINGS_SCHEMA }
)

// Angle E: Cross-file/integration issues
const angleE = await agent(
  `Review app.js for integration and architecture issues. Look for:
- Hard-coded values that should be configurable
- Tight coupling issues
- Missing dependency injection
- Server lifecycle issues
- Scalability concerns
- Testing challenges

App content:
${appContent}

Find up to 6 integration/architecture issues.`,
  { label: 'angle:architecture', phase: 'Find', schema: FINDINGS_SCHEMA }
)

// Angle F: Input validation
const angleF = await agent(
  `Review app.js specifically for input validation gaps. Look for:
- GET parameters not validated
- Query string parameters not validated
- POST body not parsed/validated
- No schema validation
- No type checking
- No length/size limits

App content:
${appContent}

Find up to 6 input validation issues.`,
  { label: 'angle:validation', phase: 'Find', schema: FINDINGS_SCHEMA }
)

// Angle G: Response handling and data exposure
const angleG = await agent(
  `Review app.js for response handling and data exposure issues. Look for:
- Hardcoded data exposed directly
- Missing response validation
- No pagination/limits on data endpoints
- Sensitive data in responses
- Missing response sanitization
- Inconsistent response formats/error responses

App content:
${appContent}

Find up to 6 data/response issues.`,
  { label: 'angle:response-handling', phase: 'Find', schema: FINDINGS_SCHEMA }
)

// Deduplicate and collect all findings
const allFindings = [angleA, angleB, angleC, angleD, angleE, angleF, angleG]
  .filter(Boolean)
  .flatMap(result => result?.findings || [])

const deduped = []
const seen = new Set()
for (const finding of allFindings) {
  const key = `${finding.file}:${finding.line}:${finding.summary}`
  if (!seen.has(key)) {
    deduped.push(finding)
    seen.add(key)
  }
}

log(`Found ${deduped.length} unique candidates across 7 angles`)

phase('Verify')

// Verify each finding
const verified = await Promise.all(
  deduped.map(finding =>
    agent(
      `Verify this finding in app.js:

FILE: ${finding.file}
LINE: ${finding.line}
SUMMARY: ${finding.summary}
SCENARIO: ${finding.failure_scenario}

Full app.js content:
${appContent}

Is this finding CONFIRMED (concrete inputs/state that trigger wrong behavior), PLAUSIBLE (real mechanism but uncertain trigger), or REFUTED (factually wrong or guarded elsewhere)?`,
      { label: `verify:${finding.line}`, phase: 'Verify', schema: VERDICT_SCHEMA }
    ).then(verdict => ({
      ...finding,
      verdict: verdict?.verdict || 'REFUTED',
      reasoning: verdict?.reasoning,
    }))
  )
)

const confirmed = verified.filter(v => v.verdict === 'CONFIRMED' || v.verdict === 'PLAUSIBLE')
  .sort((a, b) => {
    // Prioritize CONFIRMED over PLAUSIBLE
    if (a.verdict === 'CONFIRMED' && b.verdict !== 'CONFIRMED') return -1
    if (b.verdict === 'CONFIRMED' && a.verdict !== 'CONFIRMED') return 1
    return 0
  })
  .slice(0, 8)

log(`Verified: ${confirmed.length} findings remain after 1-vote verification`)

return confirmed.map(f => ({
  file: f.file,
