   - **Fix**: Configure explicit CORS:
   ```javascript
   const cors = require('cors');
   app.use(cors({
     origin: process.env.ALLOWED_ORIGINS?.split(',') || 'http://localhost:3000',
     credentials: true
   }));
   ```

### High Priority Issues

5. **No Rate Limiting**
   - **Issue**: No protection against DoS or brute force attacks.
   - **Fix**: Add rate limiting:
   ```javascript
   const rateLimit = require('express-rate-limit');
   const limiter = rateLimit({
     windowMs: 15 * 60 * 1000,
     max: 100
   });
   app.use(limiter);
   ```

6. **Hardcoded Port**
   - **Issue**: Port is hardcoded, limiting deployment flexibility and security isolation.
   - **Fix**: Use environment variables:
   ```javascript
   const PORT = process.env.PORT || 3000;
   app.listen(PORT, () => {
     console.log(`Server running on port ${PORT}`);
   });
   ```

7. **No Request Logging**
   - **Issue**: No audit trail for security monitoring.
   - **Fix**: Add request logging:
   ```javascript
   const morgan = require('morgan');
   app.use(morgan('combined'));
   ```

8. **Missing Body Parser Middleware**
   - **Issue**: If POST/PUT endpoints are added, there's no middleware to safely parse request bodies.
   - **Fix**: Add body parser:
   ```javascript
   app.use(express.json({ limit: '10kb' })); // Limit payload size
   app.use(express.urlencoded({ limit: '10kb', extended: true }));
   ```

### Medium Priority Issues

9. **No Content Security Policy**
   - **Issue**: XSS and injection attacks aren't mitigated.
   - **Note**: Helmet helps, but ensure helmet is configured for your use case.

10. **Hardcoded User Data**
    - **Issue**: Sensitive data (emails) exposed without authentication/authorization.
    - **Fix**: Add authentication middleware before sensitive endpoints:
    ```javascript
    const authenticate = (req, res, next) => {
      const token = req.headers.authorization?.split(' ')[1];
      if (!token) return res.status(401).json({ error: 'Unauthorized' });
      // Validate token...
      next();
    };

    app.get('/users', authenticate, (req, res) => { ... });
    ```

---

### 📋 Recommended Improved Version

```javascript
const express = require('express');
const helmet = require('helmet');
const cors = require('cors');
const rateLimit = require('express-rate-limit');
const morgan = require('morgan');
const { query, validationResult } = require('express-validator');

const app = express();

// Security Middleware
app.use(helmet());
app.use(cors({
  origin: process.env.ALLOWED_ORIGINS || ['http://localhost:3000'],
  credentials: true
}));

// Rate limiting
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000,
  max: 100,
  message: 'Too many requests from this IP'
});
app.use(limiter);

// Logging
app.use(morgan('combined'));

// Body parsing with size limits
app.use(express.json({ limit: '10kb' }));
app.use(express.urlencoded({ limit: '10kb', extended: true }));

// Health check (public endpoint)
app.get('/health', (req, res) => {
  res.json({ status: 'ok', timestamp: new Date().toISOString() });
});

// Users endpoint with validation
app.get('/users', 
  query('limit').optional().isInt({ min: 1, max: 100 }),
  (req, res, next) => {
    try {
      const errors = validationResult(req);
      if (!errors.isEmpty()) {
        return res.status(400).json({ errors: errors.array() });
      }

      res.json([
        { id: 1, name: 'Alice', email: 'alice@example.com' },
        { id: 2, name: 'Bob', email: 'bob@example.com' },
      ]);
    } catch (error) {
      next(error);
    }
  }
);

// 404 handler
app.use((req, res) => {
  res.status(404).json({ error: 'Not Found' });
});

// Global error handler (MUST be last)
app.use((err, req, res, next) => {
  const status = err.status || 500;
  const message = process.env.NODE_ENV === 'production' 
    ? 'Internal Server Error' 
    : err.message;

  console.error(`[${new Date().toISOString()}] Error:`, err);
  res.status(status).json({ error: message });
});

const PORT = process.env.PORT || 3000;
app.listen(PORT, () => {
  console.log(`Server running on port ${PORT}`);
});

module.exports = app;
```

### 📦 Dependencies to Add

```bash
npm install helmet cors express-rate-limit morgan express-validator
```

### ✅ Checklist for Production

- [ ] Add authentication/authorization middleware
- [ ] Implement proper logging and monitoring
- [ ] Add input validation for all endpoints
- [ ] Set security headers with Helmet
- [ ] Configure rate limiting
- [ ] Enable HTTPS in production
- [ ] Add request size limits
- [ ] Implement audit logging
- [ ] Add automated security scanning (npm audit, Snyk)
- [ ] Document API security requirements

Would you like me to help implement any of these specific improvements or create tests to verify the security enhancements?

