const rateLimit = require('express-rate-limit');
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100 // limit each IP to 100 requests per windowMs
});
app.use(limiter);
```

**6. Missing CORS Configuration** (Line 5+)
- **Risk**: Cross-origin requests may be exploited
- **Issue**: No explicit CORS policy
- **Fix**:
```javascript
const cors = require('cors');
app.use(cors({
  origin: process.env.ALLOWED_ORIGINS?.split(',') || ['http://localhost:3000'],
  credentials: true
}));
```

**7. No Request Timeout** (Line 18+)
- **Risk**: Slow client attacks, resource exhaustion
- **Issue**: Server waits indefinitely on slow clients
- **Fix**:
```javascript
app.use((req, res, next) => {
  req.setTimeout(30000); // 30 second timeout
  res.setTimeout(30000);
  next();
});
```

**8. Hardcoded Port** (Line 18)
- **Risk**: Inflexible deployment, can't follow 12-factor app principles
- **Issue**: Port 3000 hardcoded
- **Fix**:
```javascript
const PORT = process.env.PORT || 3000;
app.listen(PORT, () => {
  console.log(`Server running on port ${PORT}`);
});
```

**9. No Process Error Handlers**
- **Risk**: Unhandled promise rejections or uncaught exceptions crash the server
- **Issue**: Missing global error handlers
- **Fix**:
```javascript
process.on('unhandledRejection', (reason, promise) => {
  console.error('Unhandled Rejection at:', promise, 'reason:', reason);
  process.exit(1);
});

process.on('uncaughtException', (error) => {
