- Server crashes on error → DoS vulnerability
- No logging → can't detect or respond to attacks

**Fix**:
```javascript
// Add middleware AFTER all route definitions
app.use((err, req, res, next) => {
  // Log error securely (never log sensitive data)
  console.error(`[ERROR] ${req.method} ${req.path}:`, {
    message: err.message,
    stack: process.env.NODE_ENV === 'production' ? undefined : err.stack,
    timestamp: new Date().toISOString(),
    requestId: req.id
  });

  // Never expose stack trace to client in production
  const statusCode = err.statusCode || 500;
  const message = process.env.NODE_ENV === 'production' 
    ? 'Internal Server Error' 
    : err.message;

  res.status(statusCode).json({
    error: message,
    requestId: req.id  // For support debugging
  });
});

// Handle uncaught rejections
process.on('unhandledRejection', (reason, promise) => {
  console.error('Unhandled Rejection at:', promise, 'reason:', reason);
  process.exit(1);
});
```

---

### 3. ⚠️ MISSING SECURITY HEADERS (Global) — Severity: **HIGH**
**Issue**: No security headers; vulnerable to clickjacking, XSS, MIME-sniffing, and SSL stripping attacks

**Vulnerability**:
- No `X-Frame-Options` → clickjacking attacks possible
- No `X-Content-Type-Options` → MIME-sniffing attacks
- No `Content-Security-Policy` → XSS attacks
- No `Strict-Transport-Security` → SSL stripping attacks

**Fix**:
```javascript
const helmet = require('helmet');

app.use(helmet({
  contentSecurityPolicy: {
    directives: {
      defaultSrc: ["'self'"],
      scriptSrc: ["'self'"],
      styleSrc: ["'self'", "'unsafe-inline'"],  // Refine as needed
      imgSrc: ["'self'", 'data:'],
      upgradeInsecureRequests: []
    }
  },
  hsts: { maxAge: 31536000, includeSubDomains: true, preload: true },
  frameguard: { action: 'deny' },
  noSniff: true,
  xssFilter: true,
  referrerPolicy: { policy: 'strict-origin-when-cross-origin' }
}));
```

---

## High-Priority Issues (Should Fix)

### 4. ⚠️ MISSING REQUEST BODY PARSER (Line 1-5) — Severity: **HIGH**
**Issue**: `express.json()` middleware not configured; POST/PUT requests are not parsed

**Vulnerability**:
```javascript
// Without express.json(), req.body is undefined
app.post('/users', (req, res) => {
  console.log(req.body);  // ← undefined!
});
```

**Fix**:
```javascript
app.use(express.json({ limit: '1mb' }));  // Prevent large payload attacks
app.use(express.urlencoded({ extended: false, limit: '1mb' }));
```

---

### 5. ⚠️ HARDCODED PORT (Line 18) — Severity: **MEDIUM**
**Issue**: Server hardcoded to port 3000; fails if port unavailable

**Fix**:
```javascript
const PORT = process.env.PORT || 3000;
const HOST = process.env.HOST || 'localhost';

app.listen(PORT, HOST, () => {
  console.log(`Server running on http://${HOST}:${PORT}`);
});
```

---

### 6. ⚠️ NO INPUT VALIDATION (Line 11-16) — Severity: **MEDIUM**
**Issue**: Query parameters not validated (e.g., `?page=abc&sort=__proto__`)

**Vulnerability**: ReDoS attacks, prototype pollution, type confusion

**Fix**:
```javascript
const { query, validationResult } = require('express-validator');

app.get('/users',
  query('page').optional().isInt({ min: 1 }).toInt(),
  query('limit').optional().isInt({ min: 1, max: 100 }).toInt(),
  (req, res) => {
    const errors = validationResult(req);
    if (!errors.isEmpty()) {
      return res.status(400).json({ errors: errors.array() });
    }
    // Safe to use req.query.page and req.query.limit
  }
);
```

---

### 7. ⚠️ NO RATE LIMITING (Global) — Severity: **MEDIUM**
**Issue**: Vulnerable to brute-force, credential stuffing, and DDoS attacks

**Fix**:
```javascript
const rateLimit = require('express-rate-limit');

const limiter = rateLimit({
  windowMs: 15 * 60 * 1000,  // 15 minutes
  max: 100,                    // 100 requests per window
  message: 'Too many requests, please try again later',
  standardHeaders: true,       // Return rate limit info in RateLimit-* headers
  skip: (req) => req.ip === '127.0.0.1'  // Skip localhost for testing
});

app.use(limiter);
```

---

## Medium-Priority Issues (Nice to Have)

### 8. ⚠️ NO HTTPS/TLS (Line 18) — Severity: **MEDIUM**
**Issue**: Unencrypted HTTP allows eavesdropping on user data

**Fix** (using Node.js https module):
```javascript
const https = require('https');
const fs = require('fs');

if (process.env.NODE_ENV === 'production') {
  const options = {
    key: fs.readFileSync(process.env.TLS_KEY),
    cert: fs.readFileSync(process.env.TLS_CERT)
  };
  https.createServer(options, app).listen(PORT);
} else {
  app.listen(PORT);
}
```

Or use a reverse proxy (Nginx, HAProxy) in production.

---

## Complete Hardened Example

```javascript
const express = require('express');
const helmet = require('helmet');
const rateLimit = require('express-rate-limit');
const { query, validationResult } = require('express-validator');
const https = require('https');
const fs = require('fs');

const app = express();

// ========== SECURITY MIDDLEWARE ==========

// 1. Security headers
app.use(helmet());

// 2. Rate limiting
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000,
  max: 100,
  skip: (req) => req.ip === '127.0.0.1'
});
app.use(limiter);

// 3. Body parsing with size limits
app.use(express.json({ limit: '1mb' }));
app.use(express.urlencoded({ extended: false, limit: '1mb' }));

// ========== ROUTES ==========

app.get('/health', (req, res) => {
  try {
    res.json({ status: 'ok', timestamp: new Date().toISOString() });
  } catch (err) {
    res.status(500).json({ error: 'Health check failed' });
  }
});

app.get('/users',
  query('page').optional().isInt({ min: 1 }).toInt(),
  query('limit').optional().isInt({ min: 1, max: 100 }).toInt(),
  (req, res) => {
    const errors = validationResult(req);
    if (!errors.isEmpty()) {
      return res.status(400).json({ errors: errors.array() });
    }

    const page = req.query.page || 1;
    const limit = req.query.limit || 10;

    // Mock authentication check
    if (!req.headers.authorization) {
      return res.status(401).json({ error: 'Unauthorized' });
    }

    // Don't expose emails in list
    res.json([
      { id: 1, name: 'Alice' },
      { id: 2, name: 'Bob' }
    ]);
  }
);

// ========== ERROR HANDLING ==========

// 404 handler
app.use((req, res) => {
  res.status(404).json({ error: 'Not Found' });
});

// Global error handler (must be last)
app.use((err, req, res, next) => {
  console.error(`[ERROR] ${err.message}`);
  const statusCode = err.statusCode || 500;
  const message = process.env.NODE_ENV === 'production' 
    ? 'Internal Server Error' 
    : err.message;
  res.status(statusCode).json({ error: message });
});

// ========== SERVER STARTUP ==========

const PORT = process.env.PORT || 3000;
const HOST = process.env.HOST || '0.0.0.0';

if (process.env.NODE_ENV === 'production') {
  const options = {
    key: fs.readFileSync(process.env.TLS_KEY),
    cert: fs.readFileSync(process.env.TLS_CERT)
  };
  https.createServer(options, app).listen(PORT, HOST, () => {
    console.log(`HTTPS Server running on https://${HOST}:${PORT}`);
  });
} else {
  app.listen(PORT, HOST, () => {
    console.log(`Server running on http://${HOST}:${PORT}`);
  });
}

process.on('unhandledRejection', (reason, promise) => {
  console.error('Unhandled Rejection:', reason);
  process.exit(1);
});

module.exports = app;
```

