// Error handling, input validation, and security headers

const express = require('express');
const helmet = require('helmet');
const rateLimit = require('express-rate-limit');
const { query, validationResult } = require('express-validator');

const app = express();

// ========== SECURITY MIDDLEWARE ==========

// 1. Security headers (XSS, clickjacking, MIME-sniffing protection)
app.use(helmet({
  contentSecurityPolicy: {
    directives: {
      defaultSrc: ["'self'"],
      scriptSrc: ["'self'"],
      styleSrc: ["'self'"],
      imgSrc: ["'self'", 'data:'],
    }
  },
  hsts: { maxAge: 31536000, includeSubDomains: true },
  frameguard: { action: 'deny' },
  noSniff: true,
  xssFilter: true,
}));

// 2. Rate limiting (prevent abuse/DoS)
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000,  // 15 minutes
  max: 100,                    // Limit each IP to 100 requests per windowMs
  message: 'Too many requests from this IP, please try again later.',
  standardHeaders: true,       // Return rate limit info in RateLimit-* headers
  skip: (req) => req.ip === '127.0.0.1'  // Skip localhost for development
});
app.use(limiter);

// 3. Body parsing with size limits (prevent large payload attacks)
app.use(express.json({ limit: '1mb' }));
app.use(express.urlencoded({ extended: false, limit: '1mb' }));

// ========== ROUTES ==========

// Health check endpoint - wrapped in try-catch
app.get('/health', (req, res) => {
  try {
    res.json({
      status: 'ok',
      timestamp: new Date().toISOString(),
      uptime: process.uptime()
    });
  } catch (err) {
    res.status(500).json({ error: 'Health check failed' });
  }
});

// Users endpoint with input validation and authentication
app.get('/users',
  // Validate query parameters
  query('page')
    .optional()
    .isInt({ min: 1, max: 10000 })
    .toInt()
    .withMessage('Page must be a positive integer'),
  query('limit')
    .optional()
    .isInt({ min: 1, max: 100 })
    .toInt()
    .withMessage('Limit must be between 1 and 100'),

  // Handler
  (req, res) => {
    // Check for validation errors
    const errors = validationResult(req);
    if (!errors.isEmpty()) {
      return res.status(400).json({
        error: 'Invalid request parameters',
        details: errors.array()
      });
    }

    // TODO: Add authentication check
    // if (!req.headers.authorization) {
    //   return res.status(401).json({ error: 'Authentication required' });
    // }

    const page = req.query.page || 1;
    const limit = req.query.limit || 10;
    const offset = (page - 1) * limit;

    // Sample user data (mock database)
    const allUsers = [
      { id: 1, name: 'Alice' },
      { id: 2, name: 'Bob' },
    ];

    // Paginated response - NOTE: emails removed from public API
    const users = allUsers.slice(offset, offset + limit);

    res.json({
      data: users,
      pagination: {
        page,
        limit,
        total: allUsers.length,
        pages: Math.ceil(allUsers.length / limit)
      }
    });
  }
);

// ========== ERROR HANDLING ==========

// 404 handler for undefined routes
app.use((req, res) => {
  res.status(404).json({
    error: 'Not Found',
    path: req.path,
    method: req.method
  });
});

// Global error handler (must be last middleware)
app.use((err, req, res, next) => {
  // Log error securely (never log sensitive data)
  console.error(`[ERROR] ${new Date().toISOString()} ${req.method} ${req.path}:`, {
    message: err.message,
    // Only include stack trace in development
    stack: process.env.NODE_ENV === 'development' ? err.stack : undefined,
    statusCode: err.statusCode || 500
  });

  // Determine response status code
  const statusCode = err.statusCode || 500;

  // Never expose stack trace to client in production
  const response = {
    error: process.env.NODE_ENV === 'production'
      ? 'Internal Server Error'
      : err.message
  };

  // Add request ID for support/debugging if available
  if (req.id) {
    response.requestId = req.id;
  }

  res.status(statusCode).json(response);
});

// ========== SERVER STARTUP ==========

const PORT = process.env.PORT || 3000;
const HOST = process.env.HOST || '0.0.0.0';

app.listen(PORT, HOST, () => {
  console.log(`[INFO] Server running on http://${HOST}:${PORT}`);
  console.log(`[INFO] Environment: ${process.env.NODE_ENV || 'development'}`);
});

// Handle uncaught promise rejections
process.on('unhandledRejection', (reason, promise) => {
  console.error('[ERROR] Unhandled Promise Rejection:', reason);
  // In production, you might want to exit gracefully or alert monitoring
  process.exit(1);
});

// Handle uncaught exceptions
process.on('uncaughtException', (error) => {
  console.error('[ERROR] Uncaught Exception:', error);
  process.exit(1);
});

module.exports = app;

