// Enhanced application with security best practices
// Includes error handling, input validation, and security headers

const express = require('express');
const helmet = require('helmet');
const rateLimit = require('express-rate-limit');
const validator = require('validator');

const app = express();

// Security Middleware
app.use(helmet()); // Add security headers

// Rate limiting middleware
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // limit each IP to 100 requests per windowMs
  message: 'Too many requests from this IP, please try again later.',
  standardHeaders: true,
  legacyHeaders: false,
});

app.use(limiter); // Apply rate limiting to all routes
app.use(express.json({ limit: '10kb' })); // Limit JSON payload size
app.use(express.urlencoded({ limit: '10kb', extended: false }));

// Health check endpoint
app.get('/health', (req, res) => {
  try {
    res.json({
      status: 'ok',
      timestamp: new Date().toISOString(),
    });
  } catch (error) {
    res.status(500).json({ error: 'Internal server error' });
  }
});

// Users endpoint with input validation
app.get('/users', (req, res) => {
  try {
    // Validate and sanitize query parameters
    const { filter, limit, offset } = req.query;

    // Validate limit parameter
    let validLimit = 10; // default
    if (limit) {
      const parsedLimit = parseInt(limit, 10);
      if (!Number.isInteger(parsedLimit) || parsedLimit < 1 || parsedLimit > 100) {
        return res.status(400).json({
          error: 'Invalid limit parameter. Must be an integer between 1 and 100.',
        });
      }
      validLimit = parsedLimit;
    }

    // Validate offset parameter
    let validOffset = 0; // default
    if (offset) {
      const parsedOffset = parseInt(offset, 10);
      if (!Number.isInteger(parsedOffset) || parsedOffset < 0) {
        return res.status(400).json({
          error: 'Invalid offset parameter. Must be a non-negative integer.',
        });
      }
      validOffset = parsedOffset;
    }

    // Validate filter parameter (if provided)
    if (filter && typeof filter === 'string') {
      if (!validator.isLength(filter, { min: 1, max: 50 })) {
        return res.status(400).json({
          error: 'Invalid filter parameter. Must be between 1 and 50 characters.',
        });
      }
      // Sanitize filter input
      const sanitizedFilter = validator.escape(filter);
      console.log('Filtering users by:', sanitizedFilter);
    }

    // Mock user data (in production, fetch from database with query params)
    const users = [
      { id: 1, name: 'Alice', email: 'alice@example.com' },
      { id: 2, name: 'Bob', email: 'bob@example.com' },
    ];

    // Apply limit and offset
    const paginatedUsers = users.slice(validOffset, validOffset + validLimit);

    res.json({
      data: paginatedUsers,
      total: users.length,
      limit: validLimit,
      offset: validOffset,
    });
  } catch (error) {
    console.error('Error fetching users:', error.message);
    res.status(500).json({ error: 'Internal server error' });
  }
});

// 404 handler
app.use((req, res) => {
  res.status(404).json({ error: 'Not Found' });
});

// Global error handling middleware (must be last)
app.use((err, req, res, next) => {
  console.error('Unhandled error:', err);

  // Don't leak error details to clients in production
  const isDevelopment = process.env.NODE_ENV === 'development';
  const errorMessage = isDevelopment ? err.message : 'Internal server error';

  const statusCode = err.statusCode || 500;
  res.status(statusCode).json({
    error: errorMessage,
    ...(isDevelopment && { stack: err.stack }),
  });
});

// Server initialization with error handling
const PORT = process.env.PORT || 3000;
app.listen(PORT, () => {
  console.log(`Server running on port ${PORT}`);
});

// Graceful shutdown
process.on('SIGTERM', () => {
  console.log('SIGTERM received, shutting down gracefully...');
  process.exit(0);
});

module.exports = app;

# Security Review: app.js

## Executive Summary
The current `app.js` lacks critical security controls for a production application. This review identifies vulnerabilities and provides remediation steps following OWASP security best practices.

---

## 🔴 Critical Issues

### 1. Missing Input Validation & Sanitization
**Severity: HIGH**

**Current Code:**
```javascript
app.get('/users', (req, res) => {
  res.json([...]); // No validation of req.query
});
```

**Vulnerabilities:**
- Query injection attacks
- XSS attacks through unsanitized parameters
- Type confusion attacks
- Buffer overflow with large payloads

**Recommendation:**
```javascript
// Validate each query parameter
const limit = parseInt(req.query.limit, 10);
if (!Number.isInteger(limit) || limit < 1 || limit > 100) {
  return res.status(400).json({ error: 'Invalid limit' });
}

// Use validator library to sanitize
const filter = validator.escape(req.query.filter);
```

**Implementation:**
- Install dependencies: `npm install validator express-rate-limit helmet`
- Validate types, ranges, and lengths
- Sanitize string inputs
- Reject oversized payloads

---

### 2. No Global Error Handling Middleware
**Severity: HIGH**

**Current Code:**
```javascript
app.get('/users', (req, res) => {
  res.json([...]); // No try-catch
});
```

**Vulnerabilities:**
- Unhandled exceptions crash the server (DoS)
- Stack traces leak sensitive information
- No logging of errors
- Inconsistent error responses

**Recommendation:**
```javascript
// Add error handler at the end of app.js
app.use((err, req, res, next) => {
  console.error('Error:', err);
  const statusCode = err.statusCode || 500;
  const isDev = process.env.NODE_ENV === 'development';

  res.status(statusCode).json({
    error: isDev ? err.message : 'Internal server error',
    ...(isDev && { stack: err.stack })
  });
});
```

**Implementation:**
- Wrap all route handlers in try-catch
- Add global error middleware (must be last)
- Log errors server-side only
- Return generic errors to clients in production

---

### 3. Missing Security Headers
**Severity: MEDIUM-HIGH**

**Current Code:**
No security headers set

**Vulnerabilities:**
- XSS attacks not mitigated
- Clickjacking attacks possible
- MIME-sniffing attacks
- No protection against insecure framing

**Recommendation:**
```javascript
const helmet = require('helmet');
app.use(helmet()); // Sets multiple security headers
```

**Headers Added:**
- `X-Content-Type-Options: nosniff`
- `X-Frame-Options: DENY`
- `X-XSS-Protection: 1; mode=block`
- `Strict-Transport-Security` (HSTS)
- `Content-Security-Policy`

---

### 4. No Rate Limiting
**Severity: MEDIUM-HIGH**

**Current Code:**
Endpoints are unrestricted

**Vulnerabilities:**
- Brute force attacks on user enumeration
- DDoS attacks
- Resource exhaustion
- API abuse

**Recommendation:**
```javascript
const rateLimit = require('express-rate-limit');

const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // 100 requests per window
  message: 'Too many requests, please try again later',
});

app.use(limiter); // Apply globally or per-route
```

**Implementation:**
- Global rate limiting for all endpoints
- Stricter limits for sensitive endpoints (login, registration)
- Store in Redis for distributed systems

---

### 5. No Request Size Limiting
**Severity: MEDIUM**

**Current Code:**
No limits on request payload

**Vulnerabilities:**
- Billion laughs attack (XML bomb)
- Memory exhaustion
- Slowloris attacks

**Recommendation:**
```javascript
app.use(express.json({ limit: '10kb' }));
app.use(express.urlencoded({ limit: '10kb', extended: false }));
```

---

### 6. Exposed Sensitive Data
**Severity: MEDIUM**

**Current Code:**
```javascript
app.get('/users', (req, res) => {
  res.json([
    { id: 1, name: 'Alice', email: 'alice@example.com' },
    { id: 2, name: 'Bob', email: 'bob@example.com' },
  ]);
});
```

**Vulnerabilities:**
- No authentication check
- Email addresses exposed without authorization
- Full user enumeration possible
- Privacy violation (GDPR, CCPA)

**Recommendation:**
```javascript
app.get('/users', (req, res) => {
  // 1. Check authentication
  if (!req.user) {
    return res.status(401).json({ error: 'Unauthorized' });
  }

  // 2. Check authorization (admin role)
  if (!req.user.isAdmin) {
    return res.status(403).json({ error: 'Forbidden' });
  }

  // 3. Return data (pagination applied)
  res.json({
    data: users.slice(offset, offset + limit),
    total: users.length
  });
});
```

---

### 7. Missing Logging and Monitoring
**Severity: MEDIUM**

**Current Code:**
Only console.log for startup

**Recommendation:**
```javascript
const morgan = require('morgan');

// HTTP request logging
app.use(morgan('combined'));

// Error logging
app.use((err, req, res, next) => {
  logger.error({
    message: err.message,
    stack: err.stack,
    path: req.path,
    method: req.method,
    ip: req.ip
  });
});
```

---

## 🟡 Medium Priority Issues

### 8. No CORS Configuration
**Severity: MEDIUM**

**Recommendation:**
```javascript
const cors = require('cors');

app.use(cors({
  origin: process.env.ALLOWED_ORIGINS?.split(',') || 'http://localhost:3000',
  credentials: true,
  methods: ['GET', 'POST', 'PUT', 'DELETE'],
}));
```

---

### 9. Hardcoded Port
**Severity: LOW**

**Current Code:**
```javascript
app.listen(3000, () => {
  console.log('Server running on port 3000');
});
```

**Recommendation:**
```javascript
const PORT = process.env.PORT || 3000;
app.listen(PORT, () => {
  console.log(`Server running on port ${PORT}`);
});
```

---

### 10. No Graceful Shutdown
**Severity: LOW**

**Recommendation:**
```javascript
process.on('SIGTERM', () => {
  console.log('SIGTERM received, shutting down gracefully...');
  server.close(() => {
    console.log('Server closed');
    process.exit(0);
  });
});
```

---

## ✅ Implementation Checklist

- [ ] Add `helmet` for security headers
- [ ] Add `express-rate-limit` for rate limiting
- [ ] Add `validator` for input sanitization
- [ ] Add request size limits
- [ ] Implement global error handling middleware
- [ ] Add input validation for all query/body parameters
- [ ] Implement authentication middleware
- [ ] Add authorization checks
- [ ] Add request logging (morgan)
- [ ] Add graceful shutdown handlers
- [ ] Configure CORS appropriately
- [ ] Use environment variables for configuration
- [ ] Add environment-specific error messages
- [ ] Implement security headers
- [ ] Add 404 handler

---

## Dependencies to Install

```bash
npm install express helmet express-rate-limit validator morgan cors
```

---

## Testing Security

```bash
# Check security headers
curl -I http://localhost:3000/health

# Test rate limiting
for i in {1..150}; do curl http://localhost:3000/users; done

# Test input validation
curl "http://localhost:3000/users?limit=999999"
curl "http://localhost:3000/users?filter=<script>alert('xss')</script>"
```

---

## References

- [OWASP Top 10](https://owasp.org/www-project-top-ten/)
- [Node.js Security Best Practices](https://nodejs.org/en/docs/guides/security/)
- [Express Security Recommendations](https://expressjs.com/en/advanced/best-practice-security.html)
- [Helmet.js Documentation](https://helmetjs.github.io/)

