  try {
    // Validate query parameters
    const allowedParams = ['filter', 'sort', 'limit'];
    const givenParams = Object.keys(req.query);
    const invalidParams = givenParams.filter(p => !allowedParams.includes(p));

    if (invalidParams.length > 0) {
      return res.status(400).json({
        error: 'Invalid query parameters',
        invalid: invalidParams
      });
    }

    // Validate limit parameter if provided
    if (req.query.limit) {
      const limit = parseInt(req.query.limit, 10);
      if (isNaN(limit) || limit < 1 || limit > 100) {
        return res.status(400).json({
          error: 'Invalid limit parameter. Must be a number between 1 and 100'
        });
      }
    }

    res.json([
      { id: 1, name: 'Alice', email: 'alice@example.com' },
      { id: 2, name: 'Bob', email: 'bob@example.com' },
    ]);
  } catch (error) {
    console.error('Error in /users endpoint:', error);
    res.status(500).json({ error: 'Internal server error' });
  }
});

// ============ 404 AND ERROR HANDLERS ============

// 404 handler (must come after all other routes)
app.use((req, res) => {
  res.status(404).json({
    error: 'Not Found',
    path: req.path,
    method: req.method
  });
});

// Global error handler middleware (must be last)
app.use((err, req, res, next) => {
  console.error('Unhandled error:', err);

  // Avoid leaking error details in production
  const isDevelopment = process.env.NODE_ENV === 'development';
  const errorResponse = {
    error: 'Internal server error',
    ...(isDevelopment && { details: err.message })
  };

  const statusCode = err.statusCode || 500;
  res.status(statusCode).json(errorResponse);
});

// ============ SERVER STARTUP WITH ERROR HANDLING ============

const PORT = process.env.PORT || 3000;

const server = app.listen(PORT, () => {
  console.log(`Server running on port ${PORT}`);
});

// Handle server errors
server.on('error', (error) => {
  if (error.code === 'EADDRINUSE') {
    console.error(`Port ${PORT} is already in use`);
    process.exit(1);
  } else {
    console.error('Server error:', error);
    process.exit(1);
  }
});

// Handle unhandled promise rejections
process.on('unhandledRejection', (reason, promise) => {
  console.error('Unhandled Rejection at:', promise, 'reason:', reason);
  process.exit(1);
});

// Handle uncaught exceptions
process.on('uncaughtException', (error) => {
  console.error('Uncaught Exception:', error);
  process.exit(1);
});

module.exports = app;
