  message: 'Too many requests from this IP, please try again later.',
});
app.use(limiter);

// ============ ROUTES ============

// Health check (minimal info, no auth needed for k8s probes)
app.get('/health', (req, res) => {
  res.json({ status: 'ok' });
});

// Users endpoint (with authentication & validation)
app.get('/users', authMiddleware, validateQuery, (req, res) => {
  try {
    // Sanitize and validate query parameters
    const page = Math.max(1, parseInt(req.query.page, 10) || 1);
    const limit = Math.min(100, parseInt(req.query.limit, 10) || 10);

    const users = [
      { id: 1, name: 'Alice', email: 'alice@example.com' },
      { id: 2, name: 'Bob', email: 'bob@example.com' },
    ];

    res.json({
      data: users.slice((page - 1) * limit, page * limit),
      total: users.length,
      page,
      limit,
    });
  } catch (err) {
    res.status(400).json({ error: 'Invalid query parameters' });
  }
});

// ============ MIDDLEWARE ============

// Authentication middleware
function authMiddleware(req, res, next) {
  const token = req.headers.authorization?.replace('Bearer ', '');
  if (!token) {
    return res.status(401).json({ error: 'Unauthorized' });
  }
  // TODO: Validate JWT token
  next();
}

// Input validation middleware
function validateQuery(req, res, next) {
  const allowedParams = ['page', 'limit'];
  const invalid = Object.keys(req.query).filter(k => !allowedParams.includes(k));

  if (invalid.length > 0) {
    return res.status(400).json({ 
      error: `Invalid parameters: ${invalid.join(', ')}` 
    });
  }
  next();
}

// Global error handler (must be last)
app.use((err, req, res, next) => {
  console.error('Unhandled error:', err);
  res.status(err.status || 500).json({
    error: NODE_ENV === 'production' 
      ? 'Internal Server Error' 
      : err.message,
  });
});

// Handle 404
app.use((req, res) => {
  res.status(404).json({ error: 'Not Found' });
});

// ============ SERVER LIFECYCLE ============

const server = app.listen(PORT, () => {
  console.log(`Server running on port ${PORT} (${NODE_ENV})`);
});

// Graceful shutdown
const gracefulShutdown = () => {
  console.log('Received termination signal, shutting down gracefully...');
  server.close(() => {
    console.log('Server closed');
    process.exit(0);
  });

  // Force exit after 10 seconds
  setTimeout(() => {
    console.error('Could not close connections in time, forcefully shutting down');
    process.exit(1);
  }, 10000);
};

process.on('SIGTERM', gracefulShutdown);
process.on('SIGINT', gracefulShutdown);

// Unhandled promise rejection handler
process.on('unhandledRejection', (reason, promise) => {
  console.error('Unhandled Rejection at:', promise, 'reason:', reason);
  process.exit(1);
});

module.exports = app;
```

