export const meta = {
  name: 'security-code-review',
  description: 'Security and error handling review of app.js',
  phases: [
    { title: 'Find Issues', detail: '7 security & error handling angles' },
    { title: 'Verify', detail: 'Confirm findings' }
  ]
}

// Phase 1: Find candidates from multiple angles
phase('Find Issues')

const angles = [
  {
    label: 'input-validation',
    prompt: `Review app.js for input validation issues. Check for:
- Missing validation on request parameters/headers
- No sanitization of user inputs
- Unsafe data handling
- Missing type checks
- No rate limiting or DoS protection
The file is a simple Express.js app with /health and /users endpoints.`
  },
  {
    label: 'error-handling',
    prompt: `Review app.js for error handling gaps. Check for:
- Missing try-catch blocks
- Unhandled promise rejections
- Missing error responses
- No logging of errors
- Silent failures
- Missing validation error responses`
  },
  {
    label: 'security-headers',
    prompt: `Review app.js for security issues. Check for:
- Missing security headers (CORS, CSP, etc.)
- No HTTPS enforcement
- Missing authentication/authorization
- Information disclosure (detailed errors, timestamps)
- No request size limits
- Missing XSS/injection protections`
  },
  {
    label: 'dependency-safety',
    prompt: `Review app.js for dependency and configuration issues. Check for:
- No environment variable validation
- Hardcoded sensitive values
- Missing configuration validation
- No logging of security events
- Missing request/response validation middleware`
  },
  {
    label: 'data-exposure',
    prompt: `Review app.js for data exposure risks. Check for:
- Sensitive data in responses (emails, timestamps)
- Missing pagination on list endpoints
- No access control on /users endpoint
- Unnecessary field exposure
- Information leakage in error messages`
  },
  {
    label: 'reliability',
    prompt: `Review app.js for reliability issues. Check for:
- No graceful error handling
- Missing validation before response
- No timeout handling
- Missing resource cleanup
- No request body parsing configuration`
  },
  {
    label: 'best-practices',
    prompt: `Review app.js for Express.js best practices. Check for:
- Missing middleware setup (body-parser, helmet, etc.)
- No async error handling wrapper
- Missing request validation
- Incomplete server lifecycle
- No health check implementation details
- Missing API versioning or documentation`
  }
]

const candidates = await Promise.all(
  angles.map(angle => agent(angle.prompt, {
    label: angle.label,
    schema: {
      type: 'object',
      properties: {
        findings: {
          type: 'array',
          items: {
            type: 'object',
            properties: {
              file: { type: 'string' },
              line: { type: 'number' },
              summary: { type: 'string' },
              failure_scenario: { type: 'string' },
              severity: { type: 'string', enum: ['critical', 'high', 'medium', 'low'] }
            },
            required: ['file', 'line', 'summary', 'failure_scenario', 'severity']
          }
        }
      },
      required: ['findings']
    }
  }))
)

const allFindings = candidates.filter(Boolean).flatMap(c => c.findings)
log(`Found ${allFindings.length} candidate issues across 7 angles`)

// Dedup by line+summary
const seen = new Set()
const uniqueFindings = allFindings.filter(f => {
  const key = `${f.file}:${f.line}:${f.summary}`
  if (seen.has(key)) return false
  seen.add(key)
  return true
})

log(`After dedup: ${uniqueFindings.length} unique findings`)

// Phase 2: Verify each finding
phase('Verify')

const verified = await Promise.all(
  uniqueFindings.map(finding => 
    agent(
      `Verify this security/error-handling finding in app.js:\n\nLine ${finding.line}: ${finding.summary}\nFailure: ${finding.failure_scenario}\n\nRead app.js and confirm if this is a real issue, a plausible concern, or refuted. Return CONFIRMED/PLAUSIBLE/REFUTED with explanation.`,
      {
        label: `verify:line-${finding.line}`,
        schema: {
          type: 'object',
          properties: {
            verdict: { type: 'string', enum: ['CONFIRMED', 'PLAUSIBLE', 'REFUTED'] },
            explanation: { type: 'string' }
          },
          required: ['verdict', 'explanation']
        }
      }
    )
  )
)

const confirmed = uniqueFindings
  .map((f, i) => ({ ...f, verdict: verified[i] }))
  .filter(f => f.verdict && (f.verdict.verdict === 'CONFIRMED' || f.verdict.verdict === 'PLAUSIBLE'))
  .sort((a, b) => {
    const severityRank = { critical: 0, high: 1, medium: 2, low: 3 }
    return severityRank[a.severity] - severityRank[b.severity]
  })
  .slice(0, 8)

log(`Verified: ${confirmed.length} findings (CONFIRMED or PLAUSIBLE)`)
return confirmed

