// Hardened Express application with security best practices
// Error handling, input validation, and security headers included

const express = require('express');
const helmet = require('helmet');
const rateLimit = require('express-rate-limit');

const app = express();
const PORT = process.env.PORT || 3000;

// Security middleware
app.use(helmet()); // Set security HTTP headers

// Body parser middleware with size limits
app.use(express.json({ limit: '10kb' }));
app.use(express.urlencoded({ limit: '10kb', extended: false }));

// Rate limiting middleware
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // max 100 requests per windowMs
  message: 'Too many requests, please try again later.',
  standardHeaders: true,
  legacyHeaders: false,
});
app.use(limiter);

// Health check endpoint (no auth needed)
app.get('/health', (req, res) => {
  try {
    res.json({
      status: 'ok',
      timestamp: new Date().toISOString(),
      uptime: process.uptime(),
    });
  } catch (error) {
    res.status(500).json({ error: 'Internal server error' });
  }
});

// Users endpoint with validation and access control
app.get('/users', (req, res) => {
  try {
    // Input validation - validate query parameters
    const { limit = '10', offset = '0' } = req.query;

    // Sanitize and validate pagination parameters
    const parsedLimit = parseInt(limit, 10);
    const parsedOffset = parseInt(offset, 10);

    if (isNaN(parsedLimit) || isNaN(parsedOffset)) {
      return res.status(400).json({
        error: 'Invalid pagination parameters. limit and offset must be numbers.'
      });
    }

    if (parsedLimit < 1 || parsedLimit > 100) {
      return res.status(400).json({
        error: 'limit must be between 1 and 100'
      });
    }

    if (parsedOffset < 0) {
      return res.status(400).json({
        error: 'offset must be non-negative'
      });
    }

    // Mock data
    const allUsers = [
      { id: 1, name: 'Alice', email: 'alice@example.com' },
      { id: 2, name: 'Bob', email: 'bob@example.com' },
    ];

    // Apply pagination
    const users = allUsers.slice(parsedOffset, parsedOffset + parsedLimit);

    // Return paginated response
    res.json({
      data: users,
      total: allUsers.length,
      limit: parsedLimit,
      offset: parsedOffset,
    });
  } catch (error) {
    console.error('Error fetching users:', error);
    res.status(500).json({ error: 'Internal server error' });
  }
});

// 404 handler
app.use((req, res) => {
  res.status(404).json({ error: 'Not Found' });
});

// Global error handler (must be last)
app.use((error, req, res, next) => {
  console.error('Unhandled error:', error);

  // Don't leak error details to clients in production
  const status = error.status || 500;
  const message = process.env.NODE_ENV === 'production'
    ? 'Internal server error'
    : error.message;

  res.status(status).json({ error: message });
});

// Server startup with error handling
const server = app.listen(PORT, () => {
  console.log(`Server running on port ${PORT}`);
});

// Graceful shutdown
process.on('SIGTERM', () => {
  console.log('SIGTERM received. Shutting down gracefully...');
  server.close(() => {
    console.log('Server closed');
    process.exit(0);
  });
});

module.exports = app;

