# Security Implementation Examples

## 1. Authentication Middleware

```javascript
// middleware/auth.js
const authenticate = (req, res, next) => {
  const token = req.headers.authorization?.split(' ')[1];

  if (!token) {
    return res.status(401).json({ error: 'Missing authorization token' });
  }

  try {
    // Verify JWT token
    const decoded = jwt.verify(token, process.env.JWT_SECRET);
    req.user = decoded;
    next();
  } catch (error) {
    return res.status(403).json({ error: 'Invalid or expired token' });
  }
};

module.exports = authenticate;
```

## 2. Role-Based Access Control (RBAC)

```javascript
// middleware/authorize.js
const authorize = (requiredRoles) => {
  return (req, res, next) => {
    if (!req.user) {
      return res.status(401).json({ error: 'Not authenticated' });
    }

    if (!requiredRoles.includes(req.user.role)) {
      return res.status(403).json({ error: 'Insufficient permissions' });
    }

    next();
  };
};

module.exports = authorize;

// Usage:
app.get('/admin/users', authenticate, authorize(['admin']), (req, res) => {
  // Only admins can access this
});
```

## 3. Input Sanitization & Validation

```javascript
// utils/validators.js
const validator = require('validator');

const validateEmail = (email) => {
  if (!validator.isEmail(email)) {
    throw new Error('Invalid email format');
  }
  return email.toLowerCase();
};

const validateUserId = (id) => {
  const parsed = parseInt(id, 10);
  if (isNaN(parsed) || parsed < 1) {
    throw new Error('Invalid user ID');
  }
  return parsed;
};

const sanitizeString = (str) => {
  return validator.trim(validator.escape(str));
};

module.exports = { validateEmail, validateUserId, sanitizeString };
```

## 4. CORS Configuration

```javascript
// config/cors.js
const cors = require('cors');

const corsOptions = {
  origin: (origin, callback) => {
    const allowedOrigins = process.env.ALLOWED_ORIGINS?.split(',') || [];

    if (!origin || allowedOrigins.includes(origin)) {
      callback(null, true);
    } else {
      callback(new Error('CORS not allowed'));
    }
  },
  credentials: true,
  methods: ['GET', 'POST', 'PUT', 'DELETE'],
  allowedHeaders: ['Content-Type', 'Authorization'],
  maxAge: 86400, // 24 hours
};

module.exports = cors(corsOptions);
```

## 5. Request Validation Middleware

```javascript
// middleware/requestValidator.js
const { body, validationResult } = require('express-validator');

const validateRequest = (validations) => {
  return async (req, res, next) => {
    await Promise.all(validations.map(validation => validation.run(req)));

    const errors = validationResult(req);
    if (!errors.isEmpty()) {
      return res.status(400).json({
        error: 'Validation failed',
        details: errors.array(),
      });
    }

    next();
  };
};

module.exports = validateRequest;

// Usage:
app.post('/users', validateRequest([
  body('name').trim().isLength({ min: 1, max: 100 }),
  body('email').isEmail().normalizeEmail(),
  body('age').isInt({ min: 0, max: 150 }),
]), (req, res) => {
  // Handle request
});
```

## 6. SQL Injection Prevention

```javascript
// NEVER DO THIS (vulnerable):
const query = `SELECT * FROM users WHERE email = '${req.body.email}'`;

// DO THIS INSTEAD (safe):
const query = 'SELECT * FROM users WHERE email = ?';
db.query(query, [req.body.email], (err, results) => {
  // handle results
});

// For MongoDB (vulnerable):
db.collection('users').find({ email: req.body.email }).toArray();

// Always validate/sanitize first:
const email = validator.isEmail(req.body.email) ? req.body.email : null;
if (!email) {
  return res.status(400).json({ error: 'Invalid email' });
}
db.collection('users').find({ email }).toArray();
```

## 7. XSS Prevention

```javascript
// Bad - allows XSS:
res.json({ message: req.query.message });

// Good - sanitize output:
const sanitizeHtml = require('sanitize-html');
const safeMessage = sanitizeHtml(req.query.message, {
  allowedTags: [],
  allowedAttributes: {},
});
res.json({ message: safeMessage });

// Or use HTML escaping:
const escaped = require('html').escape(req.query.message);
res.json({ message: escaped });
```

## 8. CSRF Protection

```javascript
// Using csurf middleware
const csrf = require('csurf');
const cookieParser = require('cookie-parser');

app.use(cookieParser());
app.use(csrf({ cookie: true }));

// In forms, include CSRF token:
app.get('/form', (req, res) => {
  res.json({ csrfToken: req.csrfToken() });
});

// POST requests must include token in body or header
app.post('/submit', (req, res, next) => {
  // CSRF token automatically validated by middleware
  res.json({ success: true });
});
```

## 9. Secure Password Hashing

```javascript
// NEVER DO THIS:
const password = req.body.password;
db.query('INSERT INTO users (password) VALUES (?)', [password]);

// DO THIS INSTEAD:
const bcrypt = require('bcrypt');
const saltRounds = 10;

app.post('/register', async (req, res) => {
  try {
    const hashedPassword = await bcrypt.hash(req.body.password, saltRounds);
    db.query('INSERT INTO users (password) VALUES (?)', [hashedPassword]);
    res.json({ success: true });
  } catch (error) {
    res.status(500).json({ error: 'Registration failed' });
  }
});
```

## 10. Secure Logging (No Sensitive Data)

```javascript
// Bad - logs sensitive information:
console.log('User password:', req.body.password);
console.log('Credit card:', req.body.creditCard);

// Good - redact sensitive fields:
const redactSensitive = (obj) => {
  const sensitiveFields = ['password', 'token', 'creditCard', 'ssn', 'apiKey'];
  const copy = { ...obj };

  sensitiveFields.forEach(field => {
    if (field in copy) {
      copy[field] = '[REDACTED]';
    }
  });

  return copy;
};

console.log('User data:', redactSensitive(req.body));
```

## 11. Environment Configuration Security

```javascript
// .env file (NEVER commit this!)
NODE_ENV=production
PORT=3000
JWT_SECRET=your-secret-key-change-in-production
DATABASE_URL=postgresql://user:pass@localhost/db
