Here's a refactored version addressing all issues:

```javascript
// Secure application with error handling and validation
const express = require('express');
const helmet = require('helmet');
const rateLimit = require('express-rate-limit');
const morgan = require('morgan');
const validator = require('validator');

const app = express();

// Configuration from environment
const PORT = process.env.PORT || 3000;
const NODE_ENV = process.env.NODE_ENV || 'development';

// 1. Security Headers
app.use(helmet());

// 2. Request Logging
app.use(morgan(NODE_ENV === 'production' ? 'combined' : 'dev'));

// 3. Rate Limiting - Prevent DoS
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // limit each IP to 100 requests per windowMs
  message: 'Too many requests from this IP, please try again later.',
  standardHeaders: true,
  legacyHeaders: false,
});
app.use(limiter);

// 4. Body Parser Middleware
app.use(express.json({ limit: '10kb' })); // Limit payload size
app.use(express.urlencoded({ extended: true, limit: '10kb' }));

// 5. CORS Configuration
app.use((req, res, next) => {
  res.header('Access-Control-Allow-Origin', process.env.CORS_ORIGIN || 'localhost');
  res.header('Access-Control-Allow-Methods', 'GET, OPTIONS');
  res.header('Access-Control-Allow-Headers', 'Content-Type');

  if (req.method === 'OPTIONS') {
    return res.sendStatus(200);
  }
  next();
});

// 6. Health Check (no validation needed)
app.get('/health', (req, res) => {
  res.status(200).json({ 
    status: 'ok', 
    timestamp: new Date().toISOString(),
    uptime: process.uptime()
  });
});

// 7. Users Endpoint with Input Validation
app.get('/users', (req, res, next) => {
  try {
    // Optional: validate query parameters if filtering is added
    const { limit = 10, offset = 0 } = req.query;

    // Validate numeric inputs
    if (!Number.isInteger(Number(limit)) || Number(limit) < 1 || Number(limit) > 100) {
      return res.status(400).json({ 
        error: 'Invalid limit. Must be between 1 and 100.' 
      });
    }

    if (!Number.isInteger(Number(offset)) || Number(offset) < 0) {
      return res.status(400).json({ 
        error: 'Invalid offset. Must be >= 0.' 
      });
    }

    // Return sanitized data
    const users = [
      { id: 1, name: 'Alice', email: 'alice@example.com' },
      { id: 2, name: 'Bob', email: 'bob@example.com' },
    ];

    res.status(200).json({
      data: users.slice(offset, offset + limit),
      total: users.length,
      limit: Number(limit),
      offset: Number(offset)
    });
  } catch (error) {
    next(error); // Pass to error handler
  }
});

// 8. Not Found Handler
app.use((req, res) => {
  res.status(404).json({ 
    error: 'Not Found',
    path: req.path 
  });
});

// 9. Global Error Handler (Must be last)
app.use((err, req, res, next) => {
  const statusCode = err.statusCode || 500;
  const isDevelopment = NODE_ENV === 'development';

  // Log error (in production, use a proper logging service)
  console.error({
    timestamp: new Date().toISOString(),
    status: statusCode,
    message: err.message,
    ...(isDevelopment && { stack: err.stack })
  });

  // Don't leak stack traces in production
  res.status(statusCode).json({
    error: isDevelopment ? err.message : 'Internal Server Error',
    ...(isDevelopment && { stack: err.stack })
  });
});

// 10. Graceful Shutdown
const server = app.listen(PORT, () => {
  console.log(`Server running on port ${PORT} in ${NODE_ENV} mode`);
});

process.on('SIGTERM', () => {
  console.log('SIGTERM received, shutting down gracefully...');
  server.close(() => {
    console.log('Server closed');
    process.exit(0);
  });
});

module.exports = app;
```

