// Simple application with security best practices
// Includes error handling, input validation, and security headers

const express = require('express');
const helmet = require('helmet');
const rateLimit = require('express-rate-limit');
const cors = require('cors');

const app = express();
const PORT = process.env.PORT || 3000;

// ============ SECURITY MIDDLEWARE ============

// Add security headers using Helmet
app.use(helmet());

// Configure CORS securely
const corsOptions = {
  origin: process.env.CORS_ORIGIN || 'localhost:3000',
  credentials: true,
  methods: ['GET', 'POST'],
  maxAge: 3600,
};
app.use(cors(corsOptions));

// Parse JSON with size limit to prevent DoS
app.use(express.json({ limit: '10kb' }));

// Rate limiting middleware
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // Limit each IP to 100 requests per windowMs
  message: 'Too many requests from this IP, please try again later.',
  standardHeaders: true, // Return rate limit info in RateLimit-* headers
  legacyHeaders: false, // Disable X-RateLimit-* headers
});
app.use(limiter);

// ============ REQUEST LOGGING ============
app.use((req, res, next) => {
  const timestamp = new Date().toISOString();
  console.log(`[${timestamp}] ${req.method} ${req.path}`);
  next();
});

// ============ ROUTES ============

/**
 * Health check endpoint
 */
app.get('/health', (req, res, next) => {
  try {
    res.json({ status: 'ok', timestamp: new Date().toISOString() });
  } catch (error) {
    next(error);
  }
});

/**
 * Get users endpoint with input validation
 * Query params:
 *   - limit (optional): number of users to return (1-100)
 *   - offset (optional): pagination offset (0+)
 */
app.get('/users', (req, res, next) => {
  try {
    // Input validation
    const limit = parseInt(req.query.limit, 10) || 10;
    const offset = parseInt(req.query.offset, 10) || 0;

    // Validate input ranges
    if (!Number.isInteger(limit) || limit < 1 || limit > 100) {
      return res.status(400).json({
        error: 'Bad Request',
        message: 'limit must be between 1 and 100',
      });
    }

    if (!Number.isInteger(offset) || offset < 0) {
      return res.status(400).json({
        error: 'Bad Request',
        message: 'offset must be a non-negative integer',
      });
    }

    const allUsers = [
      { id: 1, name: 'Alice', email: 'alice@example.com' },
      { id: 2, name: 'Bob', email: 'bob@example.com' },
    ];

    // Apply pagination
    const paginatedUsers = allUsers.slice(offset, offset + limit);

    res.json({
      data: paginatedUsers,
      pagination: {
        limit,
        offset,
        total: allUsers.length,
      },
    });
  } catch (error) {
    next(error);
  }
});

// ============ ERROR HANDLING ============

// 404 handler - must come after all routes
app.use((req, res) => {
  res.status(404).json({
    error: 'Not Found',
    message: 'The requested endpoint does not exist',
    path: req.path,
  });
});

// Global error handler - must be last
app.use((err, req, res, next) => {
  console.error(`[ERROR] ${new Date().toISOString()}:`, err.message);

  // Determine status code
  const statusCode = err.statusCode || err.status || 500;

  // Don't leak internal error details to clients
  const response = {
    error: err.name || 'Internal Server Error',
    message: statusCode === 500 ? 'An unexpected error occurred' : err.message,
  };

  // Include request ID for debugging (if available)
  if (req.id) {
    response.requestId = req.id;
  }

  res.status(statusCode).json(response);
});

// ============ SERVER STARTUP ============

const server = app.listen(PORT, () => {
  console.log(`[${new Date().toISOString()}] Server running on port ${PORT}`);
});

// Handle unhandled promise rejections
process.on('unhandledRejection', (reason, promise) => {
  console.error('[UNHANDLED REJECTION]', reason);
  // In production, you may want to exit or restart the process
});

// Handle uncaught exceptions
process.on('uncaughtException', (error) => {
  console.error('[UNCAUGHT EXCEPTION]', error);
  process.exit(1);
});

// Graceful shutdown
process.on('SIGTERM', () => {
  console.log('SIGTERM received, shutting down gracefully...');
  server.close(() => {
    console.log('Server closed');
    process.exit(0);
  });
});

module.exports = app;

