// Application with security best practices
// Implements input validation, error handling, and security headers

const express = require('express');
const helmet = require('helmet');
const rateLimit = require('express-rate-limit');
const mongoSanitize = require('express-mongo-sanitize');

const app = express();

// ============= SECURITY MIDDLEWARE =============

// Enable helmet for security headers (XSS, CSRF, clickjacking protection)
app.use(helmet());

// Input validation and sanitization
app.use(express.json({ limit: '10kb' })); // Limit payload size
app.use(mongoSanitize()); // Prevent NoSQL injection

// Rate limiting to prevent brute force attacks
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // limit each IP to 100 requests per windowMs
  message: 'Too many requests from this IP, please try again later.',
  standardHeaders: true,
  legacyHeaders: false,
});

app.use(limiter);

// ============= ROUTES =============

// Health check endpoint - no data exposure
app.get('/health', (req, res) => {
  try {
    res.json({
      status: 'ok',
      timestamp: new Date().toISOString(),
    });
  } catch (error) {
    handleError(res, 'Health check failed', 500, error);
  }
});

// Protected users endpoint with authentication
app.get('/users', authenticateUser, authorizeAdmin, (req, res) => {
  try {
    // Input validation
    const { page = 1, limit = 10 } = req.query;

    // Validate pagination parameters
    if (!Number.isInteger(Number(page)) || page < 1) {
      return res.status(400).json({
        error: 'Invalid page parameter. Must be a positive integer.',
      });
    }

    if (!Number.isInteger(Number(limit)) || limit < 1 || limit > 100) {
      return res.status(400).json({
        error: 'Invalid limit parameter. Must be between 1 and 100.',
      });
    }

    // Return sanitized user data (no sensitive info exposed)
    const users = [
      { id: 1, name: 'Alice' },
      { id: 2, name: 'Bob' },
    ];

    res.json({
      data: users,
      pagination: { page, limit, total: users.length },
    });
  } catch (error) {
    handleError(res, 'Failed to fetch users', 500, error);
  }
});

// ============= MIDDLEWARE FUNCTIONS =============

// Authentication middleware - verify JWT token
function authenticateUser(req, res, next) {
  try {
    const token = req.headers.authorization?.split(' ')[1];

    if (!token) {
      return res.status(401).json({ error: 'Missing authentication token' });
    }

    // TODO: Verify JWT token with environment variable
    // const decoded = jwt.verify(token, process.env.JWT_SECRET);
    // req.user = decoded;

    next();
  } catch (error) {
    handleError(res, 'Authentication failed', 401, error);
  }
}

// Authorization middleware - check user role
function authorizeAdmin(req, res, next) {
  try {
    // TODO: Check req.user.role === 'admin'
    // if (req.user.role !== 'admin') {
    //   return res.status(403).json({ error: 'Insufficient permissions' });
    // }

    next();
  } catch (error) {
    handleError(res, 'Authorization failed', 403, error);
  }
}

// ============= ERROR HANDLING =============

// Centralized error handler
function handleError(res, message, statusCode, error) {
  // Log error securely (don't expose details to client)
  console.error(`[${statusCode}] ${message}:`, error.message);

  // Send safe response to client
  res.status(statusCode).json({
    error: message,
    // Only expose error details in development
    ...(process.env.NODE_ENV === 'development' && { details: error.message }),
  });
}

// Global error handling middleware
app.use((err, req, res, next) => {
  console.error('Unhandled error:', err);
  res.status(500).json({
    error: 'Internal server error',
    ...(process.env.NODE_ENV === 'development' && { details: err.message }),
  });
});

// 404 handler
app.use((req, res) => {
  res.status(404).json({ error: 'Endpoint not found' });
});

// ============= SERVER STARTUP =============

const PORT = process.env.PORT || 3000;
const server = app.listen(PORT, () => {
  console.log(`Server running on port ${PORT}`);
  console.log(`Environment: ${process.env.NODE_ENV || 'development'}`);
});

// Graceful shutdown
process.on('SIGTERM', () => {
  console.log('SIGTERM signal received: closing HTTP server');
  server.close(() => {
    console.log('HTTP server closed');
    process.exit(0);
  });
});

module.exports = app;

